CREATE TABLE IF NOT EXISTS stocks (
  symbol TEXT PRIMARY KEY,
  name TEXT,
  exchange TEXT,
  indices TEXT,
  currency TEXT,
  sector TEXT,
  industry TEXT,
  market_cap REAL,
  fy0 INTEGER,
  rev_est_0y REAL,
  rev_est_1y REAL,
  rev_growth_0y REAL,
  rev_growth_1y REAL,
  eps_growth_0y REAL,
  eps_growth_1y REAL,
  roe_ttm REAL,
  roe_est_0y REAL,
  roe_est_1y REAL,
  eps_est_0y REAL,
  eps_est_1y REAL,
  eps_rev_1m REAL,
  eps_rev_3m REAL,
  eps_up_30d INTEGER,
  eps_down_30d INTEGER,
  forward_pe REAL,
  pbr REAL,
  price REAL,
  high_52w REAL,
  low_52w REAL,
  chg_from_high REAL,
  chg_from_low REAL,
  chg_1m REAL,
  volume INTEGER,
  avg_vol_1y INTEGER,
  avg_vol_1w INTEGER,
  vol_chg REAL,
  inst_pct REAL,
  frgn_net_1m REAL,
  inst_net_1m REAL,
  frgn_net_3m REAL,
  inst_net_3m REAL,
  insider_net_6m INTEGER,
  short_pct REAL,
  div_yield REAL,
  op_last REAL,
  op_yoy REAL,
  updated_at TEXT
);
CREATE TABLE IF NOT EXISTS op_income_history (
  symbol TEXT NOT NULL, fiscal_year INTEGER NOT NULL, operating_income REAL,
  PRIMARY KEY (symbol, fiscal_year)
);
